n=18
G=[[1]*n for _ in range(n)]
# Split the test shape around its vertical 2-ray at column 8.
left={ (5,6),(5,7), (6,5),(6,6), (7,5),(7,6), (8,6),(8,7), (9,7), (10,5),(10,6),(10,7) }
axis={(4,8),(5,8),(9,8),(10,8)}
right={(4,9),(5,9),(5,10),(6,10),(7,9),(7,10),(7,11),(7,12),(8,10),(9,9),(9,10),(10,10),(10,11),(10,12)}
# Move each side to its corresponding top corner, independently preserving shape.
for r,c in left:
    G[r-5][c-5]=7
for r,c in right:
    G[r-4][c+5]=7
for r,c in axis:
    G[r][c]=7
# Extend the ray from the top edge through the farthest axis-aligned 7 (row 10).
for r in range(0,11):
    if G[r][8] != 7: G[r][8]=2
print('counts', {v:sum(row.count(v) for row in G) for v in (1,2,7)})
for row in G: print(' '.join(map(str,row)))
assert all(len(row)==18 for row in G) and len(G)==18
